/**
 * Expo config plugin — phone-side WatchConnectivity sender (Ripple 1.9).
 *
 * Mirrors with-app-intents.js: copies RippleWatchConnectivity.swift into the
 * generated iOS app target and compiles it, THEN adds a one-line activation to
 * the AppDelegate so the WCSession starts at launch and pushes the session
 * token (+ apiBase + streak) to the paired watch.
 *
 * Managed Expo: ios/ is regenerated by prebuild, so this must re-apply on every
 * build. Delete the plugin and the watch never receives a token.
 *
 * ── VERIFY after prebuild (do this on the device-build slice) ─────────
 *   1. ios/<projectName>/RippleWatchConnectivity.swift exists + is in the app
 *      target's PBXSourcesBuildPhase (grep the .pbxproj).
 *   2. The AppDelegate's didFinishLaunchingWithOptions contains
 *      `RippleWatchConnectivity.shared.activate()` (grep AppDelegate.swift). If
 *      the anchor didn't match (Expo changed the AppDelegate shape), this logs a
 *      warning — wire the call manually / update the anchor.
 *   3. On device: sign in on the phone, then the watch app leaves the "open on
 *      your phone" state and can record.
 */

const {
  withDangerousMod,
  withXcodeProject,
  withAppDelegate,
  IOSConfig,
} = require("expo/config-plugins");
const { mergeContents } = require("@expo/config-plugins/build/utils/generateCode");
const fs = require("fs");
const path = require("path");

const SWIFT_FILE = "RippleWatchConnectivity.swift";
const ACTIVATE_CALL = "RippleWatchConnectivity.shared.activate()";

function withSwiftCopied(config) {
  return withDangerousMod(config, [
    "ios",
    async (cfg) => {
      const { platformProjectRoot, projectName } = cfg.modRequest;
      const destDir = path.join(platformProjectRoot, projectName);
      fs.mkdirSync(destDir, { recursive: true });
      fs.copyFileSync(
        path.join(__dirname, SWIFT_FILE),
        path.join(destDir, SWIFT_FILE)
      );
      return cfg;
    },
  ]);
}

function withSwiftCompiled(config) {
  return withXcodeProject(config, (cfg) => {
    const project = cfg.modResults;
    const { projectName } = cfg.modRequest;
    const rel = `${projectName}/${SWIFT_FILE}`;
    if (project.hasFile(rel)) return cfg;
    IOSConfig.XcodeUtils.addBuildSourceFileToGroup({
      filepath: rel,
      groupName: projectName,
      project,
    });
    return cfg;
  });
}

function withAppDelegateActivation(config) {
  return withAppDelegate(config, (cfg) => {
    if (cfg.modResults.language !== "swift") {
      // eslint-disable-next-line no-console
      console.warn(
        "[with-watch-connectivity] AppDelegate is not Swift — wire " +
          `${ACTIVATE_CALL} into didFinishLaunchingWithOptions manually.`
      );
      return cfg;
    }
    if (cfg.modResults.contents.includes(ACTIVATE_CALL)) return cfg;

    const merged = mergeContents({
      tag: "ripple-watch-connectivity",
      src: cfg.modResults.contents,
      // Insert as the FIRST statement inside the launch method body. The SDK 54
      // AppDelegate signature spans multiple lines and ends with
      // `... = nil\n) -> Bool {`, so we must anchor on the body-opening brace
      // (`-> Bool {`), NOT on `didFinishLaunchingWithOptions` — anchoring on the
      // latter injects the call into the parameter list and breaks the build
      // ("expected ',' separator"). The launch method is the first `-> Bool {`
      // in the file, so the first match is the correct one.
      anchor: /-> Bool \{/,
      offset: 1,
      comment: "//",
      newSrc: `    ${ACTIVATE_CALL}`,
    });
    if (!merged.didMerge) {
      // eslint-disable-next-line no-console
      console.warn(
        "[with-watch-connectivity] could not find the didFinishLaunching " +
          `anchor — add ${ACTIVATE_CALL} to the AppDelegate manually.`
      );
      return cfg;
    }
    cfg.modResults.contents = merged.contents;
    return cfg;
  });
}

const withWatchConnectivity = (config) => {
  // eslint-disable-next-line no-console
  console.warn(
    "[with-watch-connectivity] applying: compile RippleWatchConnectivity.swift + activate WCSession at launch"
  );
  config = withSwiftCopied(config);
  config = withSwiftCompiled(config);
  config = withAppDelegateActivation(config);
  return config;
};

module.exports = withWatchConnectivity;
